/* Add event listeners for grid state changes */
function onRowClickedHandler(data) {
  let descriptionHTML = "";
  let prevewHTML = "";
  if (data.description) {
    descriptionHTML = `<div id="preview-desc">${createDescriptionHTML(data.description)}</div>`;
  }
  const preparedJsonString = data.objectsDetectedData.replaceAll(`\"`, `\\"`);
  let chooseObjectsHTML = data.icon == "image" ? formatChooseObjectsButton(data, preparedJsonString) : "";
  if ((data.previewData) && (usePreview)) {
    prevewHTML = `<div class="preview-div"><img src="${data.previewData}" onload='drawDetectedObjects("${preparedJsonString}", this)'></div>`;
  } else {
    /* If previewData is not defined, show the full image/video */
    if (data.icon == "image") {
      prevewHTML = `<div class="preview-div"><img src="${data.filePath}" onload='drawDetectedObjects("${preparedJsonString}", this)' onerror="this.onerror=null; this.src='../${data.filePath}';"></div>`;
    } else if (data.icon == "video") {
      prevewHTML = `<div class="preview-div"><video controls><source src="${data.filePath}"><source src="../${data.filePath}"></video></div>`;
    }
  }
  const chooseObjectsAndMapsLink = `<div style="align-items: center; display: flex;">${chooseObjectsHTML}${formatGoogleMapsLink(data)}</div>`;
  document.getElementById("preview_pane").innerHTML = `${chooseObjectsAndMapsLink}${prevewHTML}${descriptionHTML}`;
}

/* Column Preferences handlers */
function onColsPrefClick() {
  const colList = document.getElementById("col_list");
  colList.innerHTML = "";

  /* Get current column state from AG Grid */
  const columnState = agGridInstance.getColumnState();

  columnState.forEach(state => {
    /* Find the corresponding column definition by colId */
    const columnDef = columnDefs.find(col => col.field === state.colId);
    let label = columnDef ? columnDef.headerName : state.colId; /* Default to colId if no label found */
    if (label == iconColumnLabel) {
      label = "Icon Column";
    }
    const checked = state.hide ? "" : "checked";

    colList.insertAdjacentHTML("beforeend", `<div><input type="checkbox" class="col_checkbox" data-field="${state.colId}" ${checked}> ${label}</div>`);
  });

  document.getElementById("col_prefs").style.display = "flex";
}

