function resizePreviewDiv(e) {
  if (isResizing) {
    const delta = Math.round((e.clientX - resizeHandle.getBoundingClientRect().left));
    const newWidth = Math.round(previewDiv.getBoundingClientRect().width - Math.round(delta));
    previewDiv.style.flex = `0 0 ${newWidth}px`;
  }
}

/* Function to initialize the map for selection */
async function initMap() {
  if (!map) {
    map = L.map("map");
    /* Load OpenStreetMap tiles */
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "&copy; OpenStreetMap contributors"
    }).addTo(map);
    
    /* Add Leaflet Draw control */
    drawnItems = new L.FeatureGroup();
    map.addLayer(drawnItems);
    
    if (!markerGroup) {
      markerGroup = L.layerGroup().addTo(map);
    }

    let drawControl = new L.Control.Draw({
      draw: {
        polygon: false,
        polyline: false,
        circle: false,
        rectangle: true,
        marker: false,
        circlemarker: false
      },
      edit: {
        featureGroup: drawnItems
      }
    });
    map.addControl(drawControl);

    /* Handle rectangle drawing */
    map.on(L.Draw.Event.CREATED, function(event) {
      let layer = event.layer;
      drawnItems.addLayer(layer);

      /* Get the bounds of the drawn rectangle */
      let bounds = layer.getBounds();
    });
  } else {
    if (drawnItems) {
      drawnItems.clearLayers();
    }
  }
  
  markerGroup.clearLayers();/* Always remove previously added markers, otherwise they are accumulating on the page. */
  
  const { minLat, maxLat, minLon, maxLon } = getMaxMinCoordinates();
  const points = await getAllValidCoordinates(); /* Get all valid markers */  
  /* Ensure valid bounds exist before setting the map view */
  if (minLat === null || maxLat === null || minLon === null || maxLon === null) {
    map.setView([0, 0], 2);
    return;
  } else {
    /* Create a rectangle based on the max/min coordinates */
    const bounds = [[minLat, minLon], [maxLat, maxLon]];
    map.fitBounds(bounds);
  }

  /* Add markers with only a title (shown on hover) */
  points.forEach((marker) => {
    let options = {title: marker.title};
    if (marker.icon) {
      options.icon = marker.icon; /* Assign the custom icon only if it exists */
    }
    const addedMarkerObj = L.marker([marker.lat, marker.lon], options).addTo(map).bindPopup(marker.title);
    markerGroup.addLayer(addedMarkerObj);
  });

}

function onMapSelectionDisplay() {
  document.getElementById("map_selector").style.display = "block";
  initMap(); /* Initialize the map for selection */
}

/* Close the map selector */
function closeMapSelector() {
  document.getElementById("map_selector").style.display = "none";
}

/* Function to handle rectangle selection */
function saveRectangle() {
  var layers = drawnItems.getLayers();
  if (layers.length > 0) {
    var layer = layers[0];
    var bounds = layer.getBounds();
    var topLeft = bounds.getNorthWest();
    var bottomRight = bounds.getSouthEast();
    filterByPosition(bottomRight.lat, topLeft.lng, topLeft.lat, bottomRight.lng);
  }
  document.getElementById("map_selector").style.display = "none";
}

function selectRow(rowIndex) {
  const rowNode = agGridInstance.getDisplayedRowAtIndex(rowIndex);
  if (rowNode) {
    rowNode.setSelected(true);
    agGridInstance.ensureIndexVisible(rowIndex, "middle");
    const visibleColumns = agGridInstance.getAllDisplayedColumns();
    if ((visibleColumns) && (visibleColumns.length > 0)) {
      const firstVisibleCol = visibleColumns[0];
      agGridInstance.setFocusedCell(rowIndex, firstVisibleCol.getColId());
    }
    closeMapSelector();
  }
}

function filterByPosition(minLat, minLon, maxLat, maxLon) {
  const existingFilters = agGridInstance.getFilterModel();

  existingFilters.latitude = {
    type: "inRange",
    filter: minLat,
    filterTo: maxLat
  };

  existingFilters.longitude = {
    type: "inRange",
    filter: minLon,
    filterTo: maxLon
  };

  agGridInstance.setFilterModel(existingFilters);
}

function getMaxMinCoordinates() {
  const allRows = ((() => { const a = []; agGridInstance.forEachNode(node => {if (node.displayed) {a.push(node);}}); return a; })()); /* Get all the currently displayed rows (after filtering) */

 const { minLat, maxLat, minLon, maxLon } = allRows.reduce((acc, rowNode) => {
    const { latitude, longitude } = rowNode.data;

    /* Ignore null or undefined values */
    if (latitude != null) {
      acc.minLat = Math.min(acc.minLat, latitude);
      acc.maxLat = Math.max(acc.maxLat, latitude);
    }
    if (longitude != null) {
      acc.minLon = Math.min(acc.minLon, longitude);
      acc.maxLon = Math.max(acc.maxLon, longitude);
    }

    return acc;
  }, {
    minLat: Infinity,
    maxLat: -Infinity,
    minLon: Infinity,
    maxLon: -Infinity
  });

  /* Handle case where all values are null (to prevent Infinity from being used) */
  return {
    minLat: minLat === Infinity ? null : minLat,
    maxLat: maxLat === -Infinity ? null : maxLat,
    minLon: minLon === Infinity ? null : minLon,
    maxLon: maxLon === -Infinity ? null : maxLon
  };
}

/* Function to get all non-null lat/lon points for markers */
async function getAllValidCoordinates() {
  /* example how icon can be created. */
  /*
  var customIcon = L.icon({
    iconUrl: "data:image/png;base64,",
    iconSize: [40, 40],
    iconAnchor: [20, 40],
    popupAnchor: [0, -40]
  });*/

  const allNodes = ((() => { const a = []; agGridInstance.forEachNode(node => {if (node.displayed) {a.push(node);}}); return a; })());
  const allPoints = [];
  /* keep batchSize as 25 because with higher values sometimes this error happens: "The source image cannot be decoded." */
  const batchSize = 25;
  /*
  batch size, items, seconds - performance test. 
  100, 597, 0.7
  50, 597, 1.6
  25, 597, 1.6
  Sequentinal test 597 images - 7 seconds.
  */ 

  for (let i = 0; i < allNodes.length; i += batchSize) {
    const batch = allNodes.slice(i, i + batchSize);

    const batchResults = await Promise.all(batch.map(async (rowNode) => {
      let icon = null;
      const maxIconSize = 48;

      if (rowNode.data.previewData) {
        const iconObj = await resizeBase64Image(rowNode.data.previewData, maxIconSize);

        icon = L.icon({
          iconUrl: iconObj.imgURL,
          iconSize: [iconObj.width, iconObj.heigth],
          iconAnchor: [iconObj.width / 2, iconObj.heigth / 2],
          popupAnchor: [0, 0]
        });
      }

      return {
        lat: rowNode.data.latitude,
        lon: rowNode.data.longitude,
        title: `Row #${rowNode.rowIndex + 1}, File Name: ${rowNode.data.fileName} <a href="#" onClick="selectRow(${rowNode.rowIndex}); return false;">View</a>`,
        icon: icon
      };
    }));

    allPoints.push(...batchResults);
  }
  return allPoints ? allPoints.filter(point => point.lat != null && point.lon != null) : [];
}

async function resizeBase64Image(base64Image, maxDimension) {
  let img = new Image();
  img.src = base64Image;
  const result = {imgURL: null, width: 0, height: 0};
  try {
    /* Use img.decode() to ensure the image is fully decoded and ready for use */
    await img.decode();

    /* Create a canvas to draw the resized image */
    let canvas = document.createElement("canvas");
    let ctx = canvas.getContext("2d");

    /* Calculate the new dimensions, ensuring the largest side does not exceed maxDimension */
    let width = img.width;
    let height = img.height;

    /* Check if the image needs to be resized */
    if (width > height) {
      if (width > maxDimension) {
        height *= maxDimension / width;
        width = maxDimension;
      }
    } else {
      if (height > maxDimension) {
        width *= maxDimension / height;
        height = maxDimension;
      }
    }

    /* Set canvas dimensions and draw the image */
    canvas.width = width;
    canvas.height = height;
    ctx.drawImage(img, 0, 0, width, height);

    /* Convert the canvas to a base64 image */
    const resizedBase64 = canvas.toDataURL("image/png");
    result.imgURL = resizedBase64;
    result.height = height;
    result.width = width;
    /* Clean up the canvas and context */
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    canvas = null;
    ctx = null;

    img.src = "";
    img.onload = null;
    img.onerror = null;
    img = null;

    return result;
  } catch (error) {
    /* Handle errors during decoding */
    console.error("Error decoding the image:", error);
    throw error;
  }
}

/* Usefull service functions */
function removeDuplicates(str) {
  return [...new Set(str.split(", ").map(s => s.toLowerCase()))]
    .map((word, _, arr) => str.split(", ").find(w => w.toLowerCase() === word))
    .join(", ");
}

function extractObjLabels(item) {
  if (item.isVideo) {
    return removeDuplicates(item.framesData.flatMap(frame => frame.objectsDetected.map(detected => detected.label)).join(", "));
  } else if (item.isImage) {
    return removeDuplicates(item.objectsDetected.length > 0 ? item.objectsDetected.map(obj => obj.label).join(", ") : "");
  } else {
    return "";
  }
}

function extractOcrText(item) {
  if (item.isVideo) {
    return removeDuplicates(item.framesData.map(frame => frame.ocrText).join(", "));
  } else if (item.isImage) {
    return item.ocrText;
  } else {
    return "";
  }
}

function formatDuration(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const millis = Math.round((seconds % 1) * 1000);

  return `${String(hours).padStart(2, "0")}:` +
    `${String(minutes).padStart(2, "0")}:` +
    `${String(secs).padStart(2, "0")}.` +
    `${String(millis).padStart(3, "0")}`;
}

function parseDate(dateString) {
  let date = new Date(dateString);
  if (isNaN(date)) {
    return null;
  } else {
    return date;
  }
}

