function closeChooseObjectsPopup() {
  document.getElementById("choose_objects_popup").style.display = "none";
}

function onClickChooseObjects(event, jsonString) {
  /*choose_objects_content*/
  const chooseObjectsPopup = document.getElementById("choose_objects_popup");
  generateCheckboxList(jsonString);
  chooseObjectsPopup.style.display = "block";
  const offsetX = 10;
  const offsetY = 10;
  chooseObjectsPopup.style.left = (event.clientX + offsetX - chooseObjectsPopup.clientWidth) + "px";
  chooseObjectsPopup.style.top = (event.clientY + offsetY) + "px";
}

function generateCheckboxList(jsonString) {
  const chooseObjectsContent = document.getElementById("choose_objects_content");
  chooseObjectsContent.innerHTML = "";
  if (jsonString) {
    const detectedObjects = JSON.parse(jsonString);
    /* Sort objects by probability, that highest probability is on top of the list */
    detectedObjects.sort((a, b) => b.probability - a.probability);
    detectedObjects.forEach(item => {
      const div = document.createElement("div");
      /*div.className = "checkbox-item";*/

      let isSelected = lastSelectedObjectsToShow.some(selectedObj =>
        selectedObj.label === item.label && selectedObj.probability === item.probability
      ) || lastSelectedObjectsToShow.length == 0;
        
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.checked = isSelected;

      checkbox.dataset.label = item.label;
      checkbox.dataset.probability = item.probability;
      checkbox.addEventListener('click', () => {
        lastSelectedObjectsToShow = getSelectedObjects();
        hideAllObjects = lastSelectedObjectsToShow.length == 0;
        const selectedNode = agGridInstance.getSelectedNodes()[0];
        if (selectedNode) {
          onRowClickedHandler(selectedNode.data);
        }
      });
  
      const label = document.createElement("label");
      label.textContent = ` ${item.label} ${(item.probability * 100).toFixed(1)}%`;
  
      div.appendChild(checkbox);
      div.appendChild(label);
      chooseObjectsContent.appendChild(div);
    });
  }
}

function getSelectedObjects() {
  const container = document.getElementById('choose_objects_content');
  const checkboxes = container.querySelectorAll('input[type="checkbox"]:checked');
  const selected = [];

  checkboxes.forEach(cb => {
    selected.push({
      label: cb.dataset.label,
      probability: parseFloat(cb.dataset.probability)
    });
  });

  return selected;
}

document.getElementById("choose_objects_header").addEventListener("mousedown", function(e) {
  isChooseObjectsDragging = true;
  const chooseObjectsPopup = document.getElementById("choose_objects_popup");
  const rect = chooseObjectsPopup.getBoundingClientRect();
  chooseObjectsDivOffsetX = e.clientX - rect.left;
  chooseObjectsDivOffsetY = e.clientY - rect.top;

  document.addEventListener("mousemove", onMouseMove);
  document.addEventListener("mouseup", onMouseUp);
});

function onMouseMove(e) {
  if (!isChooseObjectsDragging) return;
  const chooseObjectsPopup = document.getElementById("choose_objects_popup");
  chooseObjectsPopup.style.left = (e.clientX - chooseObjectsDivOffsetX) + "px";
  chooseObjectsPopup.style.top = (e.clientY - chooseObjectsDivOffsetY) + "px";
}

function onMouseUp() {
  isChooseObjectsDragging = false;
  document.removeEventListener("mousemove", onMouseMove);
  document.removeEventListener("mouseup", onMouseUp);
}

function drawDetectedObjects(jsonString, img) {
  const canvasesArr = document.getElementsByTagName("canvas");
  let canvas = null;
  let ctx = null;
  if ((canvasesArr) && (canvasesArr.length > 0)) {
    /* canvas is already exist. Reuse existing */
    canvas = canvasesArr[0];
  } else {
    canvas = document.createElement("canvas");
  }

  /* clean canvas to remove previous image boxes */
  ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (jsonString) {
    const detectedObjects = JSON.parse(jsonString);
    if (detectedObjects.length > 0) {
      if (resizeObserver) {
        resizeObserver.disconnect();
        resizeObserver = null;
      }

      /* Create a new observer */
      resizeObserver = new ResizeObserver(() => {
        drawDetectedObjects(jsonString, img); /* Redraw on resize */
      });

      resizeObserver.observe(img.parentElement);

      const canvasHorisontalAdjustment = window.getComputedStyle(img.parentElement).paddingLeft.replaceAll("px", "");
      const canvasVerticalAdjustment = window.getComputedStyle(img.parentElement).paddingTop.replaceAll("px", "");

      canvas.width = img.clientWidth;
      canvas.height = img.naturalHeight * img.clientWidth / img.naturalWidth;
      canvas.style.position = "absolute";
      canvas.style.left = (img.offsetLeft + canvasHorisontalAdjustment / 2) + "px";
      canvas.style.top = (img.getBoundingClientRect().y + img.parentElement.clientHeight / 2 - canvas.height / 2 - canvasVerticalAdjustment) + "px";
      canvas.style.pointerEvents = "none";

      document.body.appendChild(canvas);
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = "#E2FA41";
      ctx.lineWidth = 2;
      ctx.font = "14px Arial";
      ctx.fillStyle = "#E2FA41";
      ctx.textBaseline = "top";
      /* sort objects by probability, that highest probability is drawn last (on top) */
      detectedObjects.sort((a, b) => a.probability - b.probability);

      /* draw objects rectangle, label and probability */
      detectedObjects.forEach(obj => {
        let isSelected = lastSelectedObjectsToShow.some(selectedObj =>
          selectedObj.label === obj.label && selectedObj.probability === obj.probability
        );
        if (((isSelected) || (lastSelectedObjectsToShow.length == 0)) && (!hideAllObjects)) {
          const { xmin, ymin, xmax, ymax } = obj.box;
  
          /* Convert relative coordinates to absolute */
          const x = xmin * canvas.width;
          const y = ymin * canvas.height;
          const width = (xmax - xmin) * canvas.width;
          const height = (ymax - ymin) * canvas.height;
  
          /* Draw bounding box */
          ctx.strokeRect(x, y, width, height);
  
          /* Display label and probability */
          const label = `${obj.label} ${(obj.probability * 100).toFixed(1)}%`;
          ctx.fillRect(x, y, ctx.measureText(label).width + 6, 20);
          ctx.fillStyle = "#000";
          ctx.fillText(label, x + 3, y + 3);
          ctx.fillStyle = "#E2FA41";
        }
      });
    }
  }
}

function logMsg(msg, objectToLog = null, isError = false, forceDebug = false) {
  if ((isDebug) || (forceDebug)) {
    const currDate = getCurrDateAsString();
    if (objectToLog) {
      if (isError) {
        console.error(`[${currDate}] [ERROR] ${msg}`, objectToLog);
      } else {
        console.log(`[${currDate}] [DEBUG] ${msg}`, objectToLog);
      }
    } else {
      if (isError) {
        console.error(`[${currDate}] [ERROR] ${msg}`);
      } else {
        console.log(`[${currDate}] [DEBUG] ${msg}`);
      }
    }
  }
}

function getCurrDateAsString() {
  const date = new Date();
  const year = date.getFullYear();
  const day = String(date.getDate()).padStart(2, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const hours = String(date.getHours()).padStart(2, "0");
  const minutes = String(date.getMinutes()).padStart(2, "0");
  const seconds = String(date.getSeconds()).padStart(2, "0");
  const milliseconds = String(date.getMilliseconds()).padStart(3, "0");

  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}.${milliseconds}`;
}

function getAgGridState() {
  const columnState = agGridInstance.getColumnState();

  /* Extract the relevant properties for each column (visibility, width) */
  const columns = columnState.map(col => ({
    colId: col.colId,
    hide: col.hide,
    width: col.width,
  }));

  /* Find the column that is currently sorted (if any) */
  const sortedColumn = columnState.find(col => col.sort);

  /* Get the order of columns (based on current columnState) */
  const columnOrder = columnState.map(col => col.colId);

  const paginationState = { itemsPerPage: agGridInstance.paginationGetPageSize() };

  return {
    columns,
    sortedColumn,
    columnOrder,
    paginationState
  };
}

function saveAgGridStateToLocalStorage() {
  const state = getAgGridState(agGridInstance);
  localStorage.setItem("MediaArchive.agGridState", JSON.stringify(state));
}

function loadAgGridStateFromLocalStorage() {
  const savedState = localStorage.getItem("MediaArchive.agGridState");
  if (!savedState) return;

  const state = JSON.parse(savedState);

  /* Set column state (visibility, width, order) using applyColumnState */
  agGridInstance.applyColumnState({
    state: state.columns.map(col => ({
      colId: col.colId,
      hide: col.hide,
      width: col.width,
    })),
    applyOrder: true,
  });

  /* Set sorting state (if any) */
  if (state.sortedColumn) {
    agGridInstance.applyColumnState({ state: [{ colId: state.sortedColumn.colId, sort: state.sortedColumn.sort }], defaultState: { sort: null } });
  }

  /* Set page size */
  if ((state.paginationState) && (state.paginationState.itemsPerPage)) {
    agGridInstance.setGridOption("paginationPageSize", state.paginationState.itemsPerPage);
  }
}

function saveUsePreview() {
  localStorage.setItem("MediaArchive.usePreview", usePreview);
}

function loadUsePreview() {
  usePreview = localStorage.getItem("MediaArchive.usePreview") == "true";
}

function formatBytes(bytes) {
  if (bytes === 0) return "0 Bytes";
  const sizes = ["Bytes", "KB", "MB", "GB", "TB"];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  const size = sizes[i];
  const value = (bytes / Math.pow(1024, i)).toFixed(2);
  return `${value} ${size}`;
}

function escapeHTML(str) {
  return str.replace(/[&<>"']/g, function (match) {
    const escape = {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      "\"": "&quot;",
      "'": "&#039;",
    };
    return escape[match];
  });
}

function createDescriptionHTML(description) {
  const MAX_LENGTH = 50;
  const needsTruncation = description.length > MAX_LENGTH;
  const shortTextRaw = needsTruncation ? description.substring(0, MAX_LENGTH) : description;

  /*const shortText = escapeHTML(escapeJSStringForHTMLAttribute(shortTextRaw));*/
  const shortText = escapeHTML(shortTextRaw);
  const fullText = escapeHTML(escapeJSStringForHTMLAttribute(description));
  closeDescPopup();
  return `${shortText}${needsTruncation ? ` <a href="#" onclick="showDescPopup(this, '${fullText}'); return false;">...</a>` : ""}`;
}

function showDescPopup(triggerElement, content) {
  const popup = document.getElementById("desc-popup");
  popup.innerHTML = `<div class="close-btn" onclick="closeDescPopup()">×</div>${content}`;
  popup.style.display = "block";
}

function closeDescPopup() {
  document.getElementById("desc-popup").style.display = "none";
}

function escapeJSStringForHTMLAttribute(str) {
  return str.replace(/\\/g, "\\\\").replace(/'/g, "\\\'").replace(/"/g, "\\\"").replace(/\n/g, "\\n").replace(/\r/g, "\\r");
}
